            if (!done[i] && dist[i] < INF && (u == -1 || dist[i] < dist[u])) {
                u = i;
            }
        }
        if (u == -1) {
            break;
        }
        done[u] = 1;
        for (int v = 1; v <= n; v++) {
            if (cost[u][v] < INF && dist[u] + cost[u][v] < dist[v]) {
                dist[v] = dist[u] + cost[u][v];
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        printf("%d%c", dist[i] == INF ? -1 : dist[i], i == n ? '\n' : ' ');
    }
    return 0;
}

